"""Writes src/styles.ts from src/style.css and src/icons.css (site) and src/editor.css (block editor)."""
import json, pathlib
src = pathlib.Path(__file__).parent / 'src'
site = (src / 'style.css').read_text() + '\n' + (src / 'icons.css').read_text()
editor = (src / 'editor.css').read_text() + '\n' + site.split('/* == Blocks == */', 1)[1]
(src / 'styles.ts').write_text(
    '// Generated by build-styles.py from style.css, icons.css and editor.css.\n'
    f'export const css = {json.dumps(site)};\nexport const editorCss = {json.dumps(editor)};\n')
